//! File reference from the actual cook registry and parser line tables.
use super::kinds;
use crate::grammar::Line;
use std::fmt::Write;

pub const PATH: &str = "crates/og-api/guides/file-types.md";

fn table(out: &mut String, fields: &[Line]) {
    out.push_str("| Field | Default | Meaning |\n|---|---|---|\n");
    for f in fields {
        let _ = writeln!(
            out,
            "| `{} {}` | `{}` | {} |",
            f.key,
            f.args.replace('|', "\\|"),
            f.default,
            f.doc.replace('|', "\\|").replace('\n', " ")
        );
    }
}

fn block(out: &mut String, name: &str, fields: &[Line]) {
    let anchor = name.replace('.', "-");
    let _ = writeln!(out, "\n<a id=\"file-{anchor}\"></a>\n### `file:{name}`\n");
    table(out, fields);
}

pub fn markdown() -> Result<String, String> {
    let mut out = String::from(
        "<!-- Generated by og api gen from reflected inputs and the cook registry. -->\n# File types\n\nUse `og api list --kind file`, `og api show file:terrain` or `og api find erosion --kind file`. Each entry states its author input: migrated domains export a typed file declaration from content/**/*.ts; domains awaiting cutover still use the listed text input. Input paths and field coverage below are per type, not runtime API fields.\n\n## 1. Cook assets\n\n",
    );
    let mut types: Vec<_> = kinds::kinds()
        .flat_map(|k| k.types.iter().map(move |t| (*t, k.name)))
        .chain(
            super::pipeline::author::KINDS
                .iter()
                .map(|(ty, k)| (*ty, k.name)),
        )
        .chain([("import", "import")])
        .collect();
    types.sort();
    for (ty, _) in types {
        if ty == "import" {
            out.push_str("<a id=\"file-import\"></a>\n### `file:import`\n\nExport file.import({kind, source, ...settings}) from content/**/*.ts. The source is an explicit owning-module assets/ or sources/ path. Checked TS feeds native import settings directly; no OGT sidecars, directory defaults or undeclared raw-file auto-cooking remain. Raw bytes, discovered model buffers/images and explicit auxiliary inputs are captured and tracked before caching. References use canonical ref('module/content-id'), never raw filenames. See loading.\n\n```ts\n");
            out.push_str(&og_core::reflect::source::typescript(
                super::source_schemas::world::import::ImportInput::schema().document(),
                "ImportInput",
            )?);
            out.push_str("```\n\n");
            continue;
        }
        if super::pipeline::author::KINDS
            .iter()
            .any(|(name, _)| *name == ty)
        {
            if ty == "table" {
                out.push_str("<a id=\"file-table\"></a>\n### `file:table`\n\nAuthor `content/**/*.ts` with `export default file.table({record: 'Item', rows: [{id: 'sword', values: {power: 12}}]})` from `@origingame/engine/author`. Run `og api gen --project <dir>` for the project's component row types and defaults. Rows have stable identities independent of order. Use canonical ref tokens for typed assets, {asset: ref(...)} for string asset IDs, {text: {key, base}} for localized strings, and {row, table?: ref(...)} for row references. Cross-table cycles are allowed; every referenced row must exist. Runtime og.table.replace accepts structured runtime values and numeric handles, never author tokens or text. No table author OGT parser remains. See data.\n\n");
                continue;
            }
            if matches!(ty, "scene" | "prefab") {
                let _ = writeln!(
                    out,
                    "<a id=\"file-{ty}\"></a>\n### `file:{ty}`\n\nAuthor `content/**/*.ts` with `export default file.{ty}({{...}})` from `@origingame/engine/author`. Run `og api gen --project <dir>` for the project's complete component/resource types, including game records. References use canonical `ref('module/content-id')`; numeric runtime handles and OGT author files are refused. Scenes supply entities, resource patches, paths, streaming groups and HLOD settings; prefabs supply one entity root and an optional base prefab. Ordered edits override fields or remove components/subtrees; computed content is evaluated only at cook. Inspector/Tune changes memory only; use checked `og set` for direct source literals.\n"
                );
                continue;
            }
            let schema = super::source_schemas::schema(ty)
                .ok_or_else(|| format!("{ty}: a TS domain needs its reflected input"))?;
            let _ = writeln!(
                out,
                "<a id=\"file-{ty}\"></a>\n### `file:{ty}`\n\nAuthor `content/**/*.ts` with `export default file[{ty:?}]({{...}})` from `@origingame/engine/author`. Project/module types are generated by `og api gen`; canonical output IDs are `<module>/<content-relative-stem>`. This domain does not accept OGT sources.\n\n```ts\n{}\n```\n",
                og_core::reflect::source::typescript(schema, "Input")?
            );
            if ty == "effect-texture" {
                out.push_str("Outputs: RGBA scattering sheet at the primary ID, thermal emission at #emission, arrays at #array and #emission#array, and their chronological #layerN textures. All parameters are required; sheet size, work budget and nonzero light direction are domain checks. Volume output is straight-alpha sRGB; noise/Worley/curl output is linear data. See effect-files for sampling and attribution.\n\n");
            }
            if ty == "sound" {
                out.push_str("Output: an ordinary sound loaded with og.load.sound. Explicit rate 8000..192000 Hz, channels 1 or 2, and at least one complete interleaved frame of finite samples are required. Float samples share the WAV importer's clamping and quantization, then the normal sound encoder and automatic streaming. Actual #chunkN outputs are reported by the producer. Oscillator synthesis remains the separate sfx domain.\n\n");
            }
            if ty == "texture-array" {
                out.push_str("Outputs: one texture array at the primary ID, plus exactly #layer0 through #layerN-1 as ordinary textures. Give 1..256 equally sized images in layer order. Each layer is an explicit canonical path relative to the owning module, such as assets/tiles/grass.png; there is no sibling/assets fallback. Image bytes participate in cook stamps, including warm-cache rebuilds. Encoding kinds are color, normal, linear, single and pixel.\n\n");
            }
            if ty == "vector" {
                out.push_str("Output: vector triangles loaded with og.load.vector. Exactly one source (an explicit canonical module-relative SVG path, such as assets/ui/emblem.svg) or inline svg string is required. The SVG subset and curve flattening remain the native tessellator's; tolerance is positive view-box units, omitted uses the longer view-box side / 2000. External SVG bytes participate in cook stamps; no sibling/assets fallback is used.\n\n");
            }
            if ty == "sfx" {
                out.push_str("Output: an ordinary mono 48 kHz sound loaded with og.load.sound. A preset or at least one layer is required; preset layers precede custom layers. Rendering is limited to 30 seconds. A sample is either inline PCM or an explicit canonical path in the owning module's assets/ or sources/; stereo recordings average to mono. Sample bytes participate in cook stamps. FM is oscillator-only. og sfx writes TS declarations or listening WAVs.\n\n");
            }
            if ty == "environment" {
                out.push_str("Output: an environment map loaded with og.load.environment. Source is exactly one of {equirect: path}, {ktx2: path}, or {faces: [px,nx,py,ny,pz,nz]}. Paths are canonical under the owning module's assets/ or sources/, without sibling fallback. Image bytes are captured before cache lookup. The existing HDR/LDR prefilter, upper hemisphere fill, sun extraction and prefiltered KTX2 chain are unchanged. Size is a power of two; prefiltered forbids samples and sun extraction. See loading and render.\n\n");
            }
            if ty == "icons" {
                out.push_str("Output: a named distance-field font loaded with og.load.font. SVG directory source is canonical relative to the owning module (default assets/icons), never relative to the declaration. icons is an ordered list of [name, SVG stem] pairs; names are unique single lines, and stems stay beneath source. Exact SVG bytes are captured before cache lookup. Native SVG stroke joins, fill, tone runs, sticker outline/shadow and atlas layout are unchanged. See theme-tokens for the shared set.\n\n");
            }
            if ty == "video" {
                out.push_str("Output: video metadata plus its actual frames/stream/poster/audio subresources. Source and audioLocale files use canonical paths under the owning module's assets/ or sources/, without sibling fallback. The closed TS evaluator and schema are shared with og video edges and flow tools. Planning, hashing, ffprobe and ffmpeg share one immutable, disk-backed media snapshot. Clip encoding, AV1 streams, alpha, localized sound and browser renditions are unchanged. Stream-only controls require stream: true; renditions: [] disables browser renditions. Requires ffmpeg/ffprobe.\n\n");
            }
            if ty == "timeline" {
                out.push_str("Output: one native timeline. Keys are {time, ease?, value}; tracks are discriminated by kind. Reference assets with ref('module/content-id'), never physical file paths. Caption imports use canonical module assets/ or sources/ paths and are captured before cache lookup. Adjacent locale translations remain discoverable; explicit locales override them. Nested timelines reject cycles and excessive depth. Internal blob text is not an author format. See animation and flow.\n\n");
            }
            if ty == "field" {
                out.push_str("Output: a lossless f32 lattice loaded with og.load.field. Positive dimensions [x,y,z], 1..4 interleaved channels and exactly their product in finite values are required, at most 16,777,216 scalars. Values run x fastest, then y, then z. Origin defaults to zero, positive spacing to one. Terrain preserve and particle fields consume the same checked lattice by canonical content ID; particles require a cubic three-channel lattice. There is no field text parser or generate wrapper. See generating.\n\n");
            }
            if ty == "terrain" {
                out.push_str("Output: independently compressed terrain tiles, control pages, horizon and hole data, loaded with og.terrain.load. Source is exactly one image, evaluated metre-valued heightfield or seeded noise. Image/control/hole paths are explicit owning-module paths (assets/ or sources/), with no sibling fallback. Process order remains hydraulic, thermal, terraces, shore, drainage, channels, preserve projection and biome controls, then ordered brush/stamp edits. Texture, array, model-geometry and preserve operands are canonical content refs. Writer, navmesh and projected scatter share one checked surface. There is no terrain OGT parser or generate.script wrapper. See generating and terrain.\n\n");
            }
            if ty == "navmesh" {
                out.push_str("Output: a baked navigation mesh loaded with og.nav.load, with one mesh per agent profile. Scene, placed model and terrain operands are canonical refs, not file paths. Cook captures imported geometry once; planning and execution do not reopen model files. Terrain uses the writer's shared checked surface. Areas explicitly select box, cylinder or convex shape and retain written overlap order. Link IDs are exact u32 values and unique; unnamed profiles take precedence, otherwise the first is default. No navigation author OGT parser remains. See world.\n\n");
            }
            if ty == "lightmap" {
                out.push_str("Output: native lighting tables and captured RGBA16F KTX2 pages. og bake lightmaps writes TS under content/lightmaps/ and pages plus dense binary bindings under assets/lightmaps/; rebaking retains existing declaration ownership. Tracked input.bytes feeds typed arrays rather than huge TS literals. UVs are flat u/v/page triples; probes have twelve flat RGB coefficients each. Scene/model assets are canonical refs; HLOD uses {hlodProxy: nodeNumber} with an empty entity. Hashes are hexadecimal strings. Pages use an explicit owning-module assets/ or sources/ path. The bundle explicitly associates at most one lightmap per scene. Warm cooks capture inputs before stamp lookup. No lightmap author text parser remains.\n\n");
            }
            if ty == "tileset" {
                out.push_str("Output: native atlas grid, collisions, tile animations and blob47/bitmask16 terrain rules. Texture is an optional canonical content ref; omit for collision-only grids. Tile IDs and frames are zero-based; durations are explicit positive seconds, one per frame (uniform fps: frames.map(() => 1 / fps)). Rectangles covering the full tile normalize to full collision. Masks must be reachable for their selected mode. Tiled/LDtk imports, embedded tilesets and snapshots share the native codec; no tileset author or runtime text parser remains. See world.\n\n");
            }
            if ty == "tilemap" {
                out.push_str("Output: a native layered map loaded with og.load.tilemap. Tilesets are ordered canonical refs; layer.tileset indexes this list. Cells are row-major top-first u32: zero empty, otherwise tile id + 1 with optional flip X (0x80000000) and Y (0x40000000); diagonal flips are refused. Terrain cells are 0/1 occupancy. Map dimensions allow at most 16,777,216 cells; every layer has exactly width * height cells and a unique name. Unit is world units per tile width; object positions/dimensions and layer offsets are map-local world units with y up. Compute cells directly in TS, using rng(seed), procgen and input.bytes as needed; no generate wrapper or author OGT parser remains. Tiled/LDtk remain external import formats. See world and generating.\n\n");
            }
            if ty == "grammar" {
                out.push_str("Output: checked native building rules consumed by districts, not a runtime blob. Numbers are literals or declared parameter names; dimensions are metres and roof angles degrees. Each ordered rule has exactly one terminal operation, last; recess and detail precede it. All rule/parameter references are checked, including unreachable rules. Insert models are canonical content refs bound through their actual outputs. District building rules name the grammar's canonical content ID. Seeded choices, shrinking recursion, detail levels and shape budgets remain the native builder's. No grammar author text parser or TS-to-OGT stage remains. See districts.\n\n");
            }
            if matches!(ty, "shader" | "post" | "ui-material") {
                out.push_str("Output: checked WGSL and ordered typed uniforms, loaded with og.load.shader, og.load.post or og.load.uiMaterial. Use code: input.text('sources/example.wgsl') for an external WGSL file; imports and exact input bytes enter the shared evaluator/cache key. Shader mode explicitly selects hooks, sprite or full with lit. Parameters select float/vec2/vec3/vec4/color; defaults are zero and colors are linear RGB. Native checks and naga validate the existing WGSL contracts for SPIR-V, MSL and HLSL before writing the binary payload. No shader-family author OGT or runtime text parser remains. See render and ui-materials.\n\n");
            }
            if ty == "motion-action" {
                out.push_str("Output: native reaction fields consumed by og.motion.react. Source and optional rig are canonical content refs, not physical paths. Requires a named clip and 0 <= holdStart < holdEnd; playback additionally checks the clip duration. Hand contact and its head-local target are optional. No motion-action author or runtime text parser remains. See animation.\n\n");
            }
            if ty == "rig" {
                out.push_str("Output: native humanoid map loaded with og.load.rig. Scheme selects auto detection or one supported naming scheme; bones map standard humanoid names to skeleton node names, with null explicitly unmapping a bone. Optional footHeight is [left,right] in metres, each -10..10. Retargeting, skin relaxation and the writer share one checked declaration snapshot. Import animation settings name the canonical rig content ID. There is no rig author or runtime text parser. See animation.\n\n");
            }
            if matches!(ty, "model" | "model-program") {
                out.push_str("Output: a native model loaded with og.load.gltf. file.model selects ordered geometry/material/pivot/plant items or a canonical model-program ref with parameters and material overrides. file['model-program'] supplies checked kernel operations directly. Model operands and animation libraries are canonical refs; font, image and projection inputs are explicit owning-module assets/ or sources/ paths, captured before caching. Options control LODs, colliders, impostors, streaming and animation. There is no model author OGT parser, bufferGeometry.generate script or sibling program guessing. Standalone og model tools may still read kernel JSON as an exchange format. See models, model and generating.\n\n");
            }
            if ty == "flipbook" {
                out.push_str("Output: native frames, clips, durations, pivots and events loaded with og.load.flipbook. Choose a canonical texture ref (grid, explicit frames and/or atlas: input.text of Aseprite/TexturePacker JSON), or animated sources at explicit owning-module assets/ or sources/ paths. Animated inputs emit #sheet. array: true emits #array and actual #array#layerN textures; all frames must share a size. Clip frames are names, never numeric-index fallback. Image bytes, external atlas text and helper imports invalidate warm cooks. No author OGT parser, text writer or sibling guessing remains. See loading.\n\n");
            }
            if ty == "strings" {
                out.push_str("Output: a native locale table loaded with og.i18n.load. Fonts are ordered canonical content refs, bound to actual font outputs. Locale/fallback tags are canonicalized; direction defaults to the locale. Entries preserve Unicode and compile ICU messages before cook. Importing the TS declaration in UI code registers only its cooked ID; author code never runs in the game. og i18n tables --json reads checked tables across modules; --index returns IDs/paths without content evaluation. Extraction writes direct literals only and refuses computed/shared expressions. No string-table author or runtime OGT parser remains. See localization.\n\n");
            }
            if ty == "behaviour" {
                out.push_str("Output: native behaviour nodes, keys, routes and state machines loaded with og.ai.load by canonical ID. Named subtree refs inline checked tree inputs; cycles, machine subtrees and conflicting routes are rejected. Helper imports and all reached subtrees invalidate warm cooks. Runtime og.ai.create accepts the same structured definition with cooked subtree IDs as strings. No behaviour author/runtime text parser or sibling guessing remains. See world.\n\n");
            }
            if matches!(ty, "dialogue" | "quest") {
                out.push_str("Output: native story data loaded with og.story.load by canonical content ID. Dialogues declare nodes, stable line/choice IDs, structured expressions, speakers and barks. Localization keys are independent of line identity. Quests declare ordered stages, objectives, rewards and shared globals. Resource fields are canonical content refs. An external Yarn file is imported explicitly as file.dialogue({yarn: input.text('sources/story.yarn'), assets: {...}}); every Yarn resource name maps to ref(id). Neither cook nor source tools scan Yarn automatically. No story author OGT parser or runtime text API remains. See story and flow.\n\n");
            }
            if ty == "materials" {
                out.push_str("Build-only material library consumed by file.district through its canonical content ID. Ordered materials hold labels, weight, tile, variation, image requests and shared native surface fields. Image inputs and generated map destinations are relative to the owning module's assets/. Generated textures have canonical #map-N outputs and never write author files. og materials brief/make read the same checked TS declaration. No material-library OGT parser remains. See districts.\n\n");
            }
            continue;
        }
        return Err(format!("cook type '{ty}' has no file field catalogue"));
    }
    out.push_str("## 2. Other engineering sources\n\n");
    for (ty, doc) in [
        (
            "project",
            "og-project.json is the ordinary project marker and sole name/engine/look authority. project.ts exports defineProject({...}); it is restricted bootstrap configuration, not an asset or a game entry. Run og check to generate contextual declarations in .og/types/author/. See start and conventions.",
        ),
        (
            "theme",
            "theme.json: compiles to pack.json and UI art. See themes and theme-tokens.",
        ),
        ("pack", "pack.json: UI style pack. See themes."),
        (
            "tsx",
            "TSX is the UI source; TS/TSX bundling is not a cook generator. See ui-tsx.",
        ),
        (
            "probe-record",
            "cooked/probes/<key>.ogt: derived bake record, not an authored input. See render.",
        ),
    ] {
        let _ = writeln!(out, "<a id=\"file-{ty}\"></a>\n### `file:{ty}`\n\n{doc}\n");
        if ty == "project" {
            out.push_str("```ts\n");
            out.push_str(&og_core::reflect::source::typescript(
                super::source_schemas::project::ProjectInput::schema().document(),
                "ProjectInput",
            )?);
            out.push_str("```\n");
        }
        if ty == "probe-record" {
            table(&mut out, super::probes::LINES);
        }
        if ty == "pack" {
            table(&mut out, og_ui_next::pack::grammar::LINES);
            block(
                &mut out,
                "pack.images.nineSlice",
                og_ui_next::pack::grammar::NINE,
            );
            block(
                &mut out,
                "pack.sounds.sound",
                og_ui_next::pack::grammar::SOUND,
            );
            let _ = writeln!(
                out,
                "\nTheme sections: {}. Palette seeds: {}. Sound/haptic events: {}. Haptic presets: {}. Scheme pairs have exactly light and dark. Theme values follow the Tailwind theme contract, not OGT syntax.\n",
                og_ui_next::pack::THEME_KEYS.join(", "),
                og_ui_next::pack::SEEDS.join(", "),
                og_ui_next::pack::SOUND_EVENTS.join(", "),
                og_ui_next::pack::HAPTIC_PRESETS.join(", ")
            );
        }
        if ty == "theme" {
            let fields: Vec<_> = og_ui_next::theme::RECIPE_KEYS.iter().map(|&key| {
                let (args, doc) = match key {
                    "with" => ("[mixin name, ...]", "Merge mixins in order after extends, before own keys; mixins cannot themselves extend or mix in."),
                    "color" => ("{source?,accent?,neutral?,danger?,variant?,scheme?}", "String-valued palette settings; scheme is light or dark."),
                    "pack" => ("pack object", "Hand-authored pack overlay applied after compiled theme and generated art; see file:pack."),
                    "ornament" => ("name | {slot: name}", "One ornament or one per button/panel/plate/slot/chip."),
                    "extends" => ("theme name", "Resolve parent first; cycles fail."),
                    "about" => ("string", "Author note."),
                    _ => ("dimension name", "Select a dimension value; no new artwork or gameplay is inferred."),
                };
                Line::new(key, args, "inherited", doc, "")
            }).collect();
            table(&mut out, &fields);
            let fields: Vec<_> = og_ui_next::theme::COLOR_KEYS.iter().map(|&key| Line::new(key, "string", "inherited", "Palette input; source/accent/neutral/danger are colours, variant selects palette derivation, scheme is light or dark.", "")).collect();
            block(&mut out, "theme.color", &fields);
        }
    }
    out.push_str("Removed style.ogt and .svelte are rejected, not compatibility formats. For native source extensions, use the loading guide; a decoder supported as a parent asset's input is not necessarily an independent cook type.\n");
    Ok(out)
}
